{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"// Deterministic reliability aggregation for Agent Dev benefit reporting.
//
// This module is pure: it never performs I/O, network calls or process side
// effects. It only classifies trial outcomes and computes aggregate metrics.
//
// Metric separation (deliberately NOT interchangeable):
//   - pass^k : fraction of *complete* cases where every one of the k trials passed.
//   - pass@k : fraction of *complete* cases where at least one of the k trials passed.
//
// Incomplete cases (a case containing a missing / timeout / crash / skip trial)
// are excluded from the metric denominator but are always preserved in the
// returned report so that nothing is silently dropped.

export const PASS_STATUS = 'pass';
export const FAIL_STATUS = 'fail';
export const INCOMPLETE_STATUSES = Object.freeze(['missing', 'timeout', 'crash', 'skip']);
export const TRIAL_STATUSES = Object.freeze([PASS_STATUS, FAIL_STATUS, ...INCOMPLETE_STATUSES]);
export const ANCHOR_KINDS = Object.freeze(['positive', 'negative']);

export const GATE_PASS = 'pass';
export const GATE_FAIL = 'fail';
export const GATE_INSUFFICIENT = 'insufficient-sample';

function round4(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) return null;
  return Math.round(value * 10000) / 10000;
}

function ratio(numerator, denominator) {
  if (!denominator) return null;
  return round4(numerator / denominator);
}

/** Normalize an arbitrary trial value to a known status. Unknown values are treated as `missing`. */
export function normalizeTrialStatus(status) {
  if (status === PASS_STATUS || status === FAIL_STATUS) return status;
  if (INCOMPLETE_STATUSES.includes(status)) return status;
  return 'missing';
}

/**
 * Classify a single case against the registered design k.
 * Missing trials (short trial arrays) are normalized to `missing`.
 */
export function classifyCase(entry, k) {
  const designK = Number.isInteger(k) && k > 0 ? k : 3;
  const source = entry && typeof entry === 'object' ? entry : {};
  const caseId = String(source.id ?? source.caseId ?? '');
  const kind = ANCHOR_KINDS.includes(source.kind) ? source.kind : 'positive';
  const safetyCritical = Boolean(source.safetyCritical);
  const rawTrials = Array.isArray(source.trials) ? source.trials : [];

  const trials = [];
  for (let index = 0; index < designK; index += 1) {
    const raw = rawTrials[index];
    const status = normalizeTrialStatus(typeof raw === 'string' ? raw : raw && raw.status);
    trials.push({
      index,
      status,
      complete: status === PASS_STATUS || status === FAIL_STATUS,
    });
  }

  const statusCounts = {};
  for (const status of TRIAL_STATUSES) statusCounts[status] = 0;
  for (const trial of trials) statusCounts[trial.status] += 1;

  const incompleteReasons = [...new Set(trials.filter((trial) => !trial.complete).map((trial) => trial.status))].sort();
  const complete = incompleteReasons.length === 0;
  const passedTrials = trials.filter((trial) => trial.status === PASS_STATUS).length;
  const failedTrials = trials.filter((trial) => trial.status === FAIL_STATUS).length;
  const allPassed = complete && passedTrials === designK;
  const anyPassed = passedTrials > 0;
  const firstTrialPassed = trials[0].status === PASS_STATUS;
  // Flake: the first trial failed and every fixed rerun afterwards succeeded.
  // The original gate failure is preserved: such a case is never `allPassed`.
  const flake = complete && trials[0].status === FAIL_STATUS && trials.slice(1).every((trial) => trial.status === PASS_STATUS);

  return {
    caseId,
    kind,
    safetyCritical,
    trials,
    statusCounts,
    incompleteReasons,
    complete,
    passedTrials,
    failedTrials,
    allPassed,
    anyPassed,
    firstTrialPassed,
    flake,
    trialSuccessRate: ratio(passedTrials, designK),
  };
}

function anchorSummary(cases, kind) {
  const scoped = cases.filter((entry) => entry.kind === kind);
  const violations = scoped.filter((entry) => entry.complete && !entry.allPassed).map((entry) => entry.caseId);
  const incomplete = scoped.filter((entry) => !entry.complete).map((entry) => entry.caseId);
  return {
    kind,
    caseIds: scoped.map((entry) => entry.caseId),
    caseCount: scoped.length,
    violations,
    incomplete,
    satisfied: violations.length === 0 && incomplete.length === 0,
  };
}

/**
 * Aggregate classified cases into the deterministic reliability report.
 *
 * @param {object} input
 * @param {Array<object>} [input.cases] raw fixture cases (`{ id, kind, safetyCritical, trials }`)
 * @param {number} [input.k] registered design k (pre-registered, e.g. 3)
 * @param {number} [input.minCases] minimum number of complete cases required for a PASS gate
 * @param {number} [input.flakeThreshold] maximum tolerated flake rate
 * @param {number} [input.safetyMaxFlakeRate] maximum tolerated flake rate for safety-critical cases
 */
export function aggregateReliability(input = {}) {
  const options = input && typeof input === 'object' ? input : {};
  const k = Number.isInteger(options.k) && options.k > 0 ? options.k : 3;
  const minCases = Number.isInteger(options.minCases) && options.minCases >= 0 ? options.minCases : 20;
  const flakeThreshold = typeof options.flakeThreshold === 'number' && Number.isFinite(options.flakeThreshold)
    ? options.flakeThreshold
    : 0;
  const safetyMaxFlakeRate = typeof options.safetyMaxFlakeRate === 'number' && Number.isFinite(options.safetyMaxFlakeRate)
    ? options.safetyMaxFlakeRate
    : 0;

  const rawCases = Array.isArray(options.cases) ? options.cases : [];
  const cases = rawCases.map((entry) => classifyCase(entry, k));
  const completeCases = cases.filter((entry) => entry.complete);
  const incompleteCases = cases.filter((entry) => !entry.complete);

  const denominator = completeCases.length;
  const passKCount = completeCases.filter((entry) => entry.allPassed).length;
  const passAtKCount = completeCases.filter((entry) => entry.anyPassed).length;
  const flakeCases = completeCases.filter((entry) => entry.flake);
  const totalTrials = denominator * k;
  const passedTrials = completeCases.reduce((sum, entry) => sum + entry.passedTrials, 0);
  const trialIndexPasses = Array.from({ length: k }, () => 0);
  for (const entry of completeCases) {
    for (const trial of entry.trials) {
      if (trial.status === PASS_STATUS) trialIndexPasses[trial.index] += 1;
    }
  }

  const incompleteBreakdown = { missing: [], timeout: [], crash: [], skip: [], other: [] };
  for (const entry of incompleteCases) {
    for (const reason of entry.incompleteReasons) {
      if (Object.prototype.hasOwnProperty.call(incompleteBreakdown, reason)) incompleteBreakdown[reason].push(entry.caseId);
      else incompleteBreakdown.other.push(entry.caseId);
    }
  }

  const positiveAnchor = anchorSummary(cases, 'positive');
  const negativeAnchor = anchorSummary(cases, 'negative');
  const anchorViolations = [...positiveAnchor.violations, ...negativeAnchor.violations];
  const anchorIncomplete = [...positiveAnchor.incomplete, ...negativeAnchor.incomplete];

  const safetyCases = cases.filter((entry) => entry.safetyCritical);
  const safetySkipCases = safetyCases.filter((entry) => entry.statusCounts.skip > 0).map((entry) => entry.caseId);
  const safetyFlakeCases = safetyCases.filter((entry) => entry.flake).map((entry) => entry.caseId);
  const safetyFlakeRate = ratio(safetyFlakeCases.length, safetyCases.length);

  const passK = ratio(passKCount, denominator);
  const passAtK = ratio(passAtKCount, denominator);
  const flakeRate = ratio(flakeCases.length, denominator);
  const perTrialSuccessRate = ratio(passedTrials, totalTrials);

  const reasons = [];
  if (positiveAnchor.violations.length > 0) {
    reasons.push(`positive anchor not fully passing: ${positiveAnchor.violations.join(', ')}`);
  }
  if (negativeAnchor.violations.length > 0) {
    reasons.push(`negative anchor not fully rejecting: ${negativeAnchor.violations.join(', ')}`);
  }
  if (safetySkipCases.length > 0) {
    reasons.push(`safety-critical case skipped: ${safetySkipCases.join(', ')}`);
  }
  if (safetyFlakeRate !== null && safetyFlakeRate > safetyMaxFlakeRate) {
    reasons.push(`safety-critical flake rate ${safetyFlakeRate} exceeds ${safetyMaxFlakeRate}`);
  }
  if (flakeRate !== null && flakeRate > flakeThreshold) {
    reasons.push(`flake rate ${flakeRate} exceeds threshold ${flakeThreshold}`);
  }

  let gate = GATE_PASS;
  if (reasons.length > 0) {
    gate = GATE_FAIL;
  } else if (anchorIncomplete.length > 0) {
    gate = GATE_INSUFFICIENT;
    reasons.push(`anchor case incomplete: ${anchorIncomplete.join(', ')}`);
  } else if (denominator < minCases) {
    gate = GATE_INSUFFICIENT;
    reasons.push(`complete cases ${denominator} below design minimum ${minCases}`);
  }

  return {
    k,
    minCases,
    flakeThreshold,
    safetyMaxFlakeRate,
    totalCases: cases.length,
    completeCases: denominator,
    incompleteCases: incompleteCases.length,
    denominator,
    passK,
    passAtK,
    passKCount,
    passAtKCount,
    flakeRate,
    flakeCaseCount: flakeCases.length,
    flakeCaseIds: flakeCases.map((entry) => entry.caseId),
    perTrialSuccessRate,
    trialIndexSuccessRates: trialIndexPasses.map((count) => ratio(count, denominator)),
    incomplete: {
      counts: {
        missing: incompleteBreakdown.missing.length,
        timeout: incompleteBreakdown.timeout.length,
        crash: incompleteBreakdown.crash.length,
        skip: incompleteBreakdown.skip.length,
        other: incompleteBreakdown.other.length,
      },
      cases: incompleteBreakdown,
      caseIds: incompleteCases.map((entry) => entry.caseId),
    },
    anchors: {
      positive: positiveAnchor,
      negative: negativeAnchor,
      violations: anchorViolations,
      incomplete: anchorIncomplete,
    },
    safety: {
      caseIds: safetyCases.map((entry) => entry.caseId),
      caseCount: safetyCases.length,
      skipCases: safetySkipCases,
      flakeCases: safetyFlakeCases,
      flakeRate: safetyFlakeRate,
    },
    gate,
    reasons,
    cases,
  };
}

export default aggregateReliability;
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"// Type declarations for scripts/lib/reliability-aggregation.mjs

export type TrialStatus = 'pass' | 'fail' | 'missing' | 'timeout' | 'crash' | 'skip';
export type AnchorKind = 'positive' | 'negative';
export type Gate = 'pass' | 'fail' | 'insufficient-sample';

export interface ReliabilityFixtureCase {
  id: string;
  kind: AnchorKind;
  safetyCritical?: boolean;
  trials: Array<TrialStatus | string | { status: TrialStatus | string }>;
}

export interface ClassifiedTrial {
  index: number;
  status: TrialStatus;
  complete: boolean;
}

export interface ClassifiedCase {
  caseId: string;
  kind: AnchorKind;
  safetyCritical: boolean;
  trials: ClassifiedTrial[];
  statusCounts: Record<TrialStatus, number>;
  incompleteReasons: TrialStatus[];
  complete: boolean;
  passedTrials: number;
  failedTrials: number;
  allPassed: boolean;
  anyPassed: boolean;
  firstTrialPassed: boolean;
  flake: boolean;
  trialSuccessRate: number | null;
}

export interface AnchorSummary {
  kind: AnchorKind;
  caseIds: string[];
  caseCount: number;
  violations: string[];
  incomplete: string[];
  satisfied: boolean;
}

export interface ReliabilityAggregationInput {
  cases?: ReliabilityFixtureCase[];
  k?: number;
  minCases?: number;
  flakeThreshold?: number;
  safetyMaxFlakeRate?: number;
}

export interface ReliabilityAggregationReport {
  k: number;
  minCases: number;
  flakeThreshold: number;
  safetyMaxFlakeRate: number;
  totalCases: number;
  completeCases: number;
  incompleteCases: number;
  denominator: number;
  passK: number | null;
  passAtK: number | null;
  passKCount: number;
  passAtKCount: number;
  flakeRate: number | null;
  flakeCaseCount: number;
  flakeCaseIds: string[];
  perTrialSuccessRate: number | null;
  trialIndexSuccessRates: Array<number | null>;
  incomplete: {
    counts: { missing: number; timeout: number; crash: number; skip: number; other: number };
    cases: Record<string, string[]>;
    caseIds: string[];
  };
  anchors: {
    positive: AnchorSummary;
    negative: AnchorSummary;
    violations: string[];
    incomplete: string[];
  };
  safety: {
    caseIds: string[];
    caseCount: number;
    skipCases: string[];
    flakeCases: string[];
    flakeRate: number | null;
  };
  gate: Gate;
  reasons: string[];
  cases: ClassifiedCase[];
}

export const PASS_STATUS: 'pass';
export const FAIL_STATUS: 'fail';
export const INCOMPLETE_STATUSES: readonly ['missing', 'timeout', 'crash', 'skip'];
export const TRIAL_STATUSES: readonly TrialStatus[];
export const ANCHOR_KINDS: readonly AnchorKind[];
export const GATE_PASS: 'pass';
export const GATE_FAIL: 'fail';
export const GATE_INSUFFICIENT: 'insufficient-sample';

export function normalizeTrialStatus(status: unknown): TrialStatus;
export function classifyCase(entry: ReliabilityFixtureCase, k: number): ClassifiedCase;
export function aggregateReliability(input?: ReliabilityAggregationInput): ReliabilityAggregationReport;

export default aggregateReliability;
